// Realtime voices: a subtractive/FM synth voice and four drum voices.
// No allocation after construction. All state is plain numbers.

const TWO_PI = 2 * Math.PI;
const DENORM = 1e-20;

function polyBlep(t, dt) {
  if (t < dt) {
    t /= dt;
    return t + t - t * t - 1;
  }
  if (t > 1 - dt) {
    t = (t - 1) / dt;
    return t * t + t + t + 1;
  }
  return 0;
}

function midiToHz(n) {
  return 440 * Math.pow(2, (n - 69) / 12);
}

// ---------------------------------------------------------------------------

class SynthVoice {
  constructor(sr) {
    this.sr = sr;
    this.active = false;
    this.p = null;
    this.age = 0;
    this.stage = 0; // 1 attack, 2 decay/sustain, 4 release
    this.env = 0;
    this.note = 0;
    this.tick = 0;
    // Wind/brass/choir features. Typed arrays: element writes do not allocate.
    this.fc = new Float64Array(12); // per formant: a1, a2, a3, gain*k
    this.fs = new Float64Array(6); // per formant: ic1, ic2
    this.nf = 0;
    this.dry = 1;
    this.breath = 0;
    this.nrng = 1;
    this.lpN = 0;
    this.be = 0;
    this.beCoef = 0;
    this.fRise = false;
    this.feCoefRise = 0;
    this.scoopNow = 0;
    this.scoopCoef = 0;
  }

  // bright: 0..1 macro. pos: -1..1 pan position. ph0: 0..1 start phase.
  start(note, vel, lenSamples, patch, bright, pos, ph0) {
    const sr = this.sr;
    const p = patch;
    this.p = p;
    this.active = true;
    this.note = note;
    this.age = 0;
    this.vel = vel;
    this.freq = 440 * Math.pow(2, (note - 69) / 12);
    this.gate = lenSamples;
    this.stage = 1;
    this.env = 0;
    this.atkInc = 1 / Math.max(1, p.a * sr);
    this.decCoef = Math.exp(-4.6 / (sr * Math.max(0.005, p.d)));
    this.relCoef = Math.exp(-4.6 / (sr * Math.max(0.005, p.r)));
    this.sustain = p.s;

    const spread = p.detune || 0;
    this.mul1 = p.osc2 ? Math.pow(2, -spread / 2400) : 1;
    this.mul2 = Math.pow(2, spread / 2400);
    this.ph1 = ph0;
    this.ph2 = (ph0 * 7.31) % 1;
    this.phs = 0;
    this.phm = 0;
    this.lfo = ph0;
    this.pwmPh = ph0;

    this.fe = 1;
    this.feCoefBlock = Math.exp(-16 / (sr * Math.max(0.01, p.fdec || 1)));
    this.fmE = 1;
    this.fmCoef = Math.exp(-4.6 / (sr * Math.max(0.05, p.fmDecay || 1)));

    // Filter envelope that rises instead of falling (brass "blat").
    this.fRise = (p.fRise || 0) > 0;
    this.feCoefRise = Math.exp(-16 / (sr * Math.max(0.005, p.fRise || 1)));
    if (this.fRise) this.fe = 0;
    // Pitch scoop into the note, in cents, settling over scoopDec seconds.
    this.scoopNow = p.scoop || 0;
    this.scoopCoef = Math.exp(-16 / (sr * Math.max(0.005, p.scoopDec || 0.06)));
    // Breath noise: deterministic seed from note and start phase.
    this.breath = p.breath || 0;
    this.nrng = (Math.imul(note + 1, 2654435761) ^ Math.floor(ph0 * 4294967295)) | 1;
    this.lpN = 0;
    this.be = 1;
    this.beCoef = Math.exp(-1 / (sr * 0.09));
    // Parallel formant (band-pass) bank, coefficients fixed for the note.
    const F = p.formants;
    this.nf = F ? Math.min(3, F.length) : 0;
    this.dry = p.dry === undefined ? 1 : p.dry;
    this.fs.fill(0);
    for (let q = 0; q < this.nf; q++) {
      const g = Math.tan((Math.PI * Math.min(F[q][0], sr * 0.4)) / sr);
      const kq = 1 / F[q][1];
      const a1f = 1 / (1 + g * (g + kq));
      this.fc[q * 4] = a1f;
      this.fc[q * 4 + 1] = g * a1f;
      this.fc[q * 4 + 2] = g * g * a1f;
      this.fc[q * 4 + 3] = F[q][2] * kq;
    }

    // Cutoff base: bright macro moves it by +-1.5 octaves.
    const track = Math.pow(this.freq / 261.63, p.key || 0);
    this.cutBase = p.cut * Math.pow(2, (bright - 0.5) * 3) * track;
    this.res = Math.min(0.95, p.res || 0);
    this.ic1 = 0;
    this.ic2 = 0;
    this.a1 = this.a2 = this.a3 = 0;
    this.tick = 0;
    this.vibMul = 1;
    this.pw = p.pw || 0.5;

    const ang = (pos * (p.pan || 0) + 1) * (Math.PI / 4);
    this.gL = Math.cos(ang) * 1.3;
    this.gR = Math.sin(ang) * 1.3;
    this.gain = p.gain * (0.35 + 0.65 * vel);
  }

  setBright(bright) {
    // Applied lazily to cutoff at next control tick for sustained voices.
    const p = this.p;
    if (!p) return;
    const track = Math.pow(this.freq / 261.63, p.key || 0);
    this.cutBase = p.cut * Math.pow(2, (bright - 0.5) * 3) * track;
  }

  release() {
    if (this.stage !== 4) this.stage = 4;
  }

  // Adds into L/R (dry), REV and DLY (mono sends). Frames [o, o+n).
  render(n, o, L, R, REV, DLY) {
    const p = this.p;
    const sr = this.sr;
    const wave = p.wave;
    const isFM = wave === 'fm';
    const isSaw = wave === 'saw';
    const isPulse = wave === 'pulse';
    const isTri = wave === 'tri';
    const isReed = wave === 'reed';
    const isOrgan = wave === 'organ';
    const two = !!p.osc2;
    const nf = this.nf;
    const fc = this.fc;
    const fs = this.fs;
    const dry = this.dry;
    const breath = this.breath;
    const beCoef = this.beCoef;
    const rise = this.fRise;
    const scoop = p.scoop || 0;
    const vibD = p.vibDelay ? p.vibDelay * sr : 0;
    const vibR = p.vibDelay ? 0.3 * sr : 0.15 * sr;
    const sub = p.sub || 0;
    const fenv = p.fenv || 0;
    const vibDepth = p.vib || 0;
    const vibInc = ((p.vibRate || 5) * 16) / sr;
    const pwmDepth = p.pwm || 0;
    const pwmInc = ((p.pwmRate || 1) * 16) / sr;
    const fmRatio = p.fmRatio || 1;
    const fmIndex = p.fmIndex || 0;
    const revS = p.rev || 0;
    const dlyS = p.dly || 0;
    const nyq = sr * 0.45;
    const oscGain = two ? 0.6 : 1;

    let env = this.env;
    let stage = this.stage;
    let ph1 = this.ph1;
    let ph2 = this.ph2;
    let phs = this.phs;
    let phm = this.phm;
    let ic1 = this.ic1;
    let ic2 = this.ic2;
    let a1 = this.a1;
    let a2 = this.a2;
    let a3 = this.a3;
    let k = 2 - 2 * this.res;
    let fmE = this.fmE;
    let gate = this.gate;
    let tick = this.tick;
    const freq = this.freq;
    let pw = this.pw;
    let vibMul = this.vibMul;
    let nr = this.nrng;
    let lpN = this.lpN;
    let be = this.be;

    for (let i = 0; i < n; i++) {
      if ((tick & 15) === 0) {
        // Control-rate update every 16 samples.
        if (rise) this.fe = 1 - (1 - this.fe) * this.feCoefRise;
        else this.fe *= this.feCoefBlock;
        let fc = this.cutBase + fenv * this.fe;
        if (fc > nyq) fc = nyq;
        if (fc < 20) fc = 20;
        const g = Math.tan((Math.PI * fc) / sr);
        a1 = 1 / (1 + g * (g + k));
        a2 = g * a1;
        a3 = g * a2;
        this.lfo += vibInc;
        if (this.lfo >= 1) this.lfo -= 1;
        if (vibDepth || scoop) {
          let cents = 0;
          if (vibDepth) {
            let fade = (this.age - vibD) / vibR;
            fade = fade < 0 ? 0 : fade > 1 ? 1 : fade;
            cents = vibDepth * fade * Math.sin(TWO_PI * this.lfo);
          }
          if (scoop) {
            this.scoopNow *= this.scoopCoef;
            cents -= this.scoopNow;
          }
          vibMul = Math.pow(2, cents / 1200);
        }
        if (pwmDepth) {
          this.pwmPh += pwmInc;
          if (this.pwmPh >= 1) this.pwmPh -= 1;
          pw = (p.pw || 0.5) + pwmDepth * Math.sin(TWO_PI * this.pwmPh);
          if (pw < 0.08) pw = 0.08;
          if (pw > 0.92) pw = 0.92;
        }
      }
      tick++;

      // Oscillators
      let x;
      const f1 = freq * this.mul1 * vibMul;
      if (isFM) {
        const dtc = f1 / sr;
        ph1 += dtc;
        if (ph1 >= 1) ph1 -= 1;
        phm += dtc * fmRatio;
        if (phm >= 1) phm -= 1;
        fmE *= this.fmCoef;
        x = Math.sin(TWO_PI * (ph1 + fmIndex * (0.25 + 0.75 * fmE) * this.vel * Math.sin(TWO_PI * phm)));
      } else {
        const dt1 = f1 / sr;
        ph1 += dt1;
        if (ph1 >= 1) ph1 -= 1;
        if (isSaw) {
          x = 2 * ph1 - 1 - polyBlep(ph1, dt1);
        } else if (isPulse) {
          x = ph1 < pw ? 1 : -1;
          x += polyBlep(ph1, dt1);
          let t2 = ph1 - pw;
          if (t2 < 0) t2 += 1;
          x -= polyBlep(t2, dt1);
        } else if (isReed) {
          // Saw plus a narrow pulse: buzzy, even and odd harmonics.
          let q = ph1 < 0.38 ? 1 : -1;
          q += polyBlep(ph1, dt1);
          let t3 = ph1 - 0.38;
          if (t3 < 0) t3 += 1;
          q -= polyBlep(t3, dt1);
          x = 0.6 * (2 * ph1 - 1 - polyBlep(ph1, dt1)) + 0.4 * q;
        } else if (isOrgan) {
          x =
            0.45 * Math.sin(TWO_PI * ph1) +
            0.3 * Math.sin(TWO_PI * 2 * ph1) +
            0.2 * Math.sin(TWO_PI * 3 * ph1) +
            0.12 * Math.sin(TWO_PI * 4 * ph1);
        } else if (isTri) {
          x = 4 * Math.abs(ph1 - 0.5) - 1;
        } else {
          x = Math.sin(TWO_PI * ph1);
        }
        if (two) {
          const dt2 = (freq * this.mul2 * vibMul) / sr;
          ph2 += dt2;
          if (ph2 >= 1) ph2 -= 1;
          let y;
          if (isSaw) {
            y = 2 * ph2 - 1 - polyBlep(ph2, dt2);
          } else if (isPulse) {
            y = ph2 < pw ? 1 : -1;
            y += polyBlep(ph2, dt2);
            let t2 = ph2 - pw;
            if (t2 < 0) t2 += 1;
            y -= polyBlep(t2, dt2);
          } else {
            y = Math.sin(TWO_PI * ph2);
          }
          x += y;
        }
        x *= oscGain;
      }
      if (sub) {
        phs += (freq * 0.5) / sr;
        if (phs >= 1) phs -= 1;
        x += sub * Math.sin(TWO_PI * phs);
      }

      // State-variable lowpass (TPT)
      const v3 = x - ic2;
      const v1 = a1 * ic1 + a2 * v3;
      const v2 = ic2 + a2 * ic1 + a3 * v3;
      ic1 = 2 * v1 - ic1;
      ic2 = 2 * v2 - ic2;

      // Optional formant bank (parallel band-passes) and breath noise.
      let sig = v2;
      if (nf > 0) {
        let acc = v2 * dry;
        for (let q = 0; q < nf; q++) {
          const b = q * 4;
          const s = q * 2;
          const f1c = fs[s];
          const f2c = fs[s + 1];
          const v3f = v2 - f2c;
          const v1f = fc[b] * f1c + fc[b + 1] * v3f;
          const v2f = f2c + fc[b + 1] * f1c + fc[b + 2] * v3f;
          fs[s] = 2 * v1f - f1c;
          fs[s + 1] = 2 * v2f - f2c;
          acc += fc[b + 3] * v1f;
        }
        sig = acc;
      }
      if (breath > 0) {
        nr = (Math.imul(nr, 1664525) + 1013904223) | 0;
        const nz = nr / 2147483648;
        lpN += 0.3 * (nz - lpN);
        be *= beCoef;
        sig += breath * (0.35 + 0.65 * be) * (nz - lpN);
      }

      // Amp envelope
      if (stage === 1) {
        env += this.atkInc;
        if (env >= 1) {
          env = 1;
          stage = 2;
        }
      } else if (stage === 2) {
        env = this.sustain + (env - this.sustain) * this.decCoef;
        if (env < 1e-4 && this.sustain < 1e-4) {
          this.active = false;
          break;
        }
      } else {
        env *= this.relCoef;
        if (env < 1e-4) {
          this.active = false;
          break;
        }
      }
      if (stage !== 4) {
        gate -= 1;
        if (gate <= 0) stage = 4;
      }

      const out = sig * env * this.gain;
      const idx = o + i;
      L[idx] += out * this.gL;
      R[idx] += out * this.gR;
      REV[idx] += out * revS;
      DLY[idx] += out * dlyS;
    }

    this.env = env;
    this.stage = stage;
    this.ph1 = ph1;
    this.ph2 = ph2;
    this.phs = phs;
    this.phm = phm;
    this.ic1 = ic1 + DENORM;
    this.ic2 = ic2 + DENORM;
    this.a1 = a1;
    this.a2 = a2;
    this.a3 = a3;
    this.fmE = fmE;
    this.gate = gate;
    this.tick = tick;
    this.pw = pw;
    this.vibMul = vibMul;
    this.nrng = nr;
    this.lpN = lpN;
    this.be = be;
    this.age += n;
  }
}

// ---------------------------------------------------------------------------

const K_KICK = 1;
const K_SNARE = 2;
const K_HAT = 3;
const K_TOM = 4;

// All per-sample state lives in locals inside render() and is written back
// once per call: object-field double stores allocate in V8 and would feed the
// garbage collector from the audio thread.
class DrumVoice {
  constructor(sr, seed) {
    this.sr = sr;
    this.active = false;
    this.kind = 0;
    this.rng = (seed | 0) || 12345;
    this.age = 0;
    this.vel = 0;
    this.ph = 0;
    this.lp1 = 0;
    this.lp2 = 0;
    this.env = 0;
    this.pitchEnv = 0;
    this.toneEnv = 0;
    this.ampCoef = 0;
    this.pitchCoef = 0;
    this.toneCoef = 0;
    this.hpA = 0;
    this.f0 = 0;
    this.fSpan = 0;
    this.rev = 0;
  }

  start(voice, note, vel) {
    const sr = this.sr;
    this.active = true;
    this.age = 0;
    this.vel = vel;
    this.ph = 0;
    this.lp1 = 0;
    this.lp2 = 0;
    this.env = 1;
    this.pitchEnv = 1;
    this.toneEnv = 1;
    this.toneCoef = 0;
    this.pitchCoef = 0;
    this.hpA = 0;
    this.f0 = 0;
    this.fSpan = 0;
    if (voice === 'kick') {
      this.kind = K_KICK;
      this.ampCoef = Math.exp(-1 / (sr * 0.075));
      this.pitchCoef = Math.exp(-1 / (sr * 0.028));
      this.f0 = 44;
      this.fSpan = 150;
      this.rev = 0;
    } else if (voice === 'snare') {
      this.kind = K_SNARE;
      this.ampCoef = Math.exp(-1 / (sr * 0.075));
      this.toneCoef = Math.exp(-1 / (sr * 0.045));
      this.pitchCoef = Math.exp(-1 / (sr * 0.02));
      this.hpA = 1 - Math.exp((-TWO_PI * 1400) / sr);
      this.rev = 0.22;
    } else if (voice === 'hat') {
      this.kind = K_HAT;
      const open = note === 46;
      this.ampCoef = Math.exp(-1 / (sr * (open ? 0.11 : 0.022)));
      this.hpA = 1 - Math.exp((-TWO_PI * 7000) / sr);
      this.rev = 0.12;
    } else {
      this.kind = K_TOM;
      this.ampCoef = Math.exp(-1 / (sr * 0.17));
      this.pitchCoef = Math.exp(-1 / (sr * 0.05));
      this.f0 = 440 * Math.pow(2, (note - 69) / 12);
      this.fSpan = this.f0 * 0.8;
      this.rev = 0.3;
    }
  }

  // Adds to L/R (centre) and REV for frames [o, o+n).
  render(n, o, L, R, REV) {
    const kind = this.kind;
    const sr = this.sr;
    const gain = this.vel * 0.55;
    const rev = this.rev;
    const ampCoef = this.ampCoef;
    const pitchCoef = this.pitchCoef;
    const toneCoef = this.toneCoef;
    const hpA = this.hpA;
    const f0 = this.f0;
    const fSpan = this.fSpan;
    let env = this.env;
    let pe = this.pitchEnv;
    let te = this.toneEnv;
    let ph = this.ph;
    let lp1 = this.lp1;
    let lp2 = this.lp2;
    let rng = this.rng;
    const age = this.age;
    let done = false;
    let i = 0;
    for (; i < n; i++) {
      let out;
      if (kind === K_KICK) {
        pe *= pitchCoef;
        ph += (f0 + fSpan * pe) / sr;
        if (ph >= 1) ph -= 1;
        let click = 0;
        if (age + i < 40) {
          rng = (Math.imul(rng, 1664525) + 1013904223) | 0;
          click = (rng / 2147483648) * 0.25;
        }
        out = Math.tanh(1.8 * Math.sin(TWO_PI * ph)) * env * 0.9 + click * env;
      } else if (kind === K_SNARE) {
        rng = (Math.imul(rng, 1664525) + 1013904223) | 0;
        const nz = rng / 2147483648;
        lp1 += hpA * (nz - lp1);
        pe *= pitchCoef;
        ph += (175 + 70 * pe) / sr;
        if (ph >= 1) ph -= 1;
        te *= toneCoef;
        out = (nz - lp1) * env * 0.7 + Math.sin(TWO_PI * ph) * te * 0.45;
      } else if (kind === K_HAT) {
        rng = (Math.imul(rng, 1664525) + 1013904223) | 0;
        const nz = rng / 2147483648;
        lp1 += hpA * (nz - lp1);
        const h1 = nz - lp1;
        lp2 += hpA * (h1 - lp2);
        out = (h1 - lp2) * env * 0.9;
      } else {
        pe *= pitchCoef;
        ph += (f0 + fSpan * pe) / sr;
        if (ph >= 1) ph -= 1;
        out = Math.sin(TWO_PI * ph) * env * 0.9;
      }
      env *= ampCoef;
      out *= gain;
      const idx = o + i;
      L[idx] += out;
      R[idx] += out;
      REV[idx] += out * rev;
      if (env < 1e-4) {
        done = true;
        i++;
        break;
      }
    }
    if (done) this.active = false;
    this.env = env;
    this.pitchEnv = pe;
    this.toneEnv = te;
    this.ph = ph;
    this.lp1 = lp1;
    this.lp2 = lp2;
    this.rng = rng;
    this.age = age + i;
  }
}


/* ---- engine/instrument.js ---- */
// Procedural lead instrument: a complete synth patch (see patches.js for the
// fields) generated from a seed, so every place gets its own instrument.
//
// An instrument is a combination of independent choices: oscillator (saw,
// pulse, triangle, FM, reed, organ), envelope (plucked or sustained), filter
// movement, vibrato, vowel-like formants, breath, pitch scoop, effect sends
// and register. The choices are correlated just enough to keep the result
// musical. Pure function of the Rng: same seed, same instrument.


const fr = (r, lo, hi) => lo + r.float() * (hi - lo);

// Loudness matching. Random parameters change the level a lot (a plucked FM
// bell versus a sustained organ), so each new instrument is rendered briefly
// at a low sample rate and its gain set so it sits at the level of the
// built-in leads. About 1 ms of work, once per place change.
const PROBE_SR = 16000;
const PROBE_N = 5600; // 0.35 s
const PROBE_GATE = 3200; // note held for 0.2 s
const TARGET_DB = -21.2; // measured on the built-in leads with probeDb()
let probe = null;
let probePeak = 0; // peak of the last probeDb() call

// Mean power (dB) of one note of a patch, as heard through the probe.
function probeDb(patch, note) {
  if (!probe) {
    probe = {
      v: new SynthVoice(PROBE_SR),
      L: new Float32Array(PROBE_N),
      R: new Float32Array(PROBE_N),
      REV: new Float32Array(PROBE_N),
      DLY: new Float32Array(PROBE_N),
    };
  }
  const { v, L, R, REV, DLY } = probe;
  L.fill(0);
  R.fill(0);
  REV.fill(0);
  DLY.fill(0);
  v.start(note, 0.7, PROBE_GATE, patch, 0.5, 0, 0.3);
  for (let o = 0; o < PROBE_N; o += 128) v.render(Math.min(128, PROBE_N - o), o, L, R, REV, DLY);
  let sum = 0;
  let pk = 0;
  for (let i = 0; i < PROBE_N; i++) {
    const x = L[i] + R[i];
    sum += x * x;
    if (x > pk) pk = x;
    else if (-x > pk) pk = -x;
  }
  probePeak = pk;
  return 10 * Math.log10(sum / PROBE_N + 1e-12);
}

function makeInstrument(r) {
  const wave = r.pick(['saw', 'saw', 'pulse', 'tri', 'fm', 'fm', 'reed', 'organ']);
  const plucked = r.chance(0.4);
  const p = { wave, detune: 0, osc2: false, sub: 0, res: 0, key: fr(r, 0.2, 0.7), pwm: 0 };

  // Oscillator.
  if (wave === 'saw' || wave === 'pulse') {
    if (r.chance(0.6)) {
      p.osc2 = true;
      p.detune = fr(r, 4, 18);
    }
  }
  if (wave === 'pulse') {
    p.pw = fr(r, 0.15, 0.5);
    if (r.chance(0.6)) {
      p.pwm = fr(r, 0.05, 0.22);
      p.pwmRate = fr(r, 0.3, 3.5);
    }
  }
  if (wave === 'fm') {
    p.fmRatio = r.pick([0.5, 1, 1, 2, 2, 3, 3.5, 4, 5]);
    p.fmIndex = fr(r, 0.3, 3);
    p.fmDecay = plucked ? fr(r, 0.12, 0.5) : fr(r, 0.6, 2);
  }
  if (r.chance(0.25)) p.sub = fr(r, 0.15, 0.45);

  // Filter.
  p.cut = fr(r, 1200, 6500);
  p.fenv = r.chance(0.7) ? fr(r, 500, 4000) : 0;
  p.fdec = fr(r, 0.06, 0.6);
  p.res = r.chance(0.5) ? fr(r, 0, 0.45) : 0.05;
  if (wave === 'saw' && !plucked && r.chance(0.3)) {
    // Brass-like: the filter opens after the attack.
    p.cut = fr(r, 700, 1200);
    p.fenv = fr(r, 2500, 4500);
    p.fRise = fr(r, 0.04, 0.12);
    p.fdec = 1;
  }

  // Envelope.
  if (plucked) {
    p.a = fr(r, 0.002, 0.012);
    p.d = fr(r, 0.12, 0.6);
    p.s = fr(r, 0, 0.15);
    p.r = fr(r, 0.12, 0.5);
  } else {
    p.a = fr(r, 0.01, 0.18);
    p.d = fr(r, 0.1, 0.4);
    p.s = fr(r, 0.6, 0.95);
    p.r = fr(r, 0.08, 0.5);
  }

  // Vibrato.
  if (r.chance(plucked ? 0.25 : 0.75)) {
    p.vib = fr(r, 5, 24);
    p.vibRate = fr(r, 4.6, 6.4);
    p.vibDelay = fr(r, 0.1, 0.5);
  }

  // Vowel-like formants and breath (not for FM or organ, which have their own timbre).
  if (wave !== 'fm' && wave !== 'organ' && r.chance(0.45)) {
    const f1 = fr(r, 380, 900);
    const f2 = f1 * fr(r, 1.8, 3.2);
    p.formants = [
      [f1, fr(r, 2, 5), 1],
      [f2, fr(r, 2.5, 5), fr(r, 0.3, 0.6)],
      [f2 * fr(r, 1.3, 1.9), fr(r, 3, 6), fr(r, 0.1, 0.3)],
    ];
    p.dry = fr(r, 0.15, 0.55);
  }
  p.breath = r.chance(0.5) ? fr(r, 0.01, 0.12) : 0;
  if (!plucked && r.chance(0.3)) {
    p.scoop = fr(r, 15, 60);
    p.scoopDec = fr(r, 0.04, 0.1);
  }

  // Space and register.
  p.rev = fr(r, 0.2, 0.55);
  p.dly = fr(r, 0.1, 0.45);
  p.pan = fr(r, 0, 0.4);
  const reg = r.pick([[48, 72], [55, 79], [60, 84], [67, 93]]);
  p.lo = reg[0];
  p.hi = reg[1];

  // Gain: render two notes of the register and scale to the target level.
  p.gain = 0.2;
  const mid = (p.lo + p.hi) >> 1;
  const db1 = probeDb(p, mid);
  const pk1 = probePeak;
  const db2 = probeDb(p, mid - 7);
  const peak = Math.max(pk1, probePeak, 1e-6);
  let g = 0.2 * Math.pow(10, (TARGET_DB - 0.5 * (db1 + db2)) / 20);
  g = Math.min(g, (0.2 * 0.5) / peak); // a single note never peaks above ~0.5
  p.gain = Math.max(0.04, Math.min(0.9, g));
  p.name = describe(p, plucked);
  return p;
}

// A small variation of an instrument for each song section (the same
// instrument, slightly brighter or duller, a different amount of vibrato).
function morphInstrument(base, r) {
  const m = { ...base };
  m.cut = base.cut * fr(r, 0.75, 1.3);
  if (base.fmIndex !== undefined) m.fmIndex = base.fmIndex * fr(r, 0.8, 1.25);
  if (base.vib !== undefined) m.vib = base.vib * fr(r, 0.7, 1.3);
  return m;
}

// Short human-readable description, e.g. "plucked FM bell, airy".
function describe(p, plucked) {
  let body;
  switch (p.wave) {
    case 'fm':
      body = p.fmRatio >= 3.4 ? 'FM bell' : 'FM tone';
      break;
    case 'saw':
      body = p.fRise ? 'brass' : 'saw';
      break;
    case 'pulse':
      body = p.pwm ? 'pulse (moving)' : 'pulse';
      break;
    case 'tri':
      body = 'flute-like tone';
      break;
    case 'reed':
      body = 'reed';
      break;
    default:
      body = 'organ';
  }
  const shape = plucked ? 'plucked' : p.a > 0.08 ? 'swelling' : 'sustained';
  const extra = [];
  if (p.formants) extra.push('vocal');
  if (p.breath > 0.06) extra.push('airy');
  if (p.scoop) extra.push('scooped');
  if (p.vib) extra.push('vibrato');
  if (p.osc2 && p.detune > 10) extra.push('wide');
  return `${shape} ${body}` + (extra.length ? ', ' + extra.slice(0, 2).join(', ') : '');
}


/* ---- engine/composer.js ---- */
// Procedural composer. Pure function of (seed, bar count): no audio, no
// floating-point state that depends on the platform beyond IEEE basics, and
// every random draw comes from a seeded stream, so the same seed always
// produces the same music.
//
// nextBar() returns a plan for one bar (16 sixteenth-note steps):
//   steps[s] = array of note events { voice, note, vel, len }
// voices: pad, bass, arp, lead, kick, snare, hat, tom


const STEPS_PER_BAR = 16;
const MAX_BPM_STEP = 12;
// At full speed (100 km/h) every style reaches at least this tempo, so a slow
// style like Abyss does not top out at 70 bpm.
const FOLLOW_TOP_BPM = 160;
const BPM_MIN = 40;
const BPM_MAX = 220;
const METER = [1, 0.15, 0.3, 0.15, 0.6, 0.15, 0.3, 0.15, 0.8, 0.15, 0.3, 0.15, 0.6, 0.15, 0.3, 0.15];
const LAYERS = ['pad', 'bass', 'arp', 'lead', 'drums'];

class Composer {
  constructor() {
    this.pending = null;
    this.s = null;
    this.barCount = 0;
    this.leadOv = null;
    this.leadProc = false;
    this.tone = { key: -1, scale: 'auto', quarter: true };
    this.lastIn = null; // the seed the current song was latched from
    this.tempoFactor = null;
    this.tempoOv = null;
    this.curBpm = null;
  }

  // seed: { style: -1 (auto) | index, coarse: u32, fine: u32 }
  setSeed(seed) {
    this.pending = { style: seed.style, coarse: seed.coarse >>> 0, fine: seed.fine >>> 0 };
  }

  hasPending() {
    return this.pending !== null;
  }

  // Tempo follows movement: factor 0..1 maps across the style's tempo range
  // (a little beyond it at both ends). null = use the tempo from the seed.
  // Applied gradually at bar lines (see nextBar).
  setTempoFactor(f) {
    this.tempoFactor = f === null || f === undefined ? null : Math.max(0, Math.min(1, f));
  }

  // Manual tempo (BPM slider): wins over movement and the seed, and applies at
  // once rather than being slewed. null returns to movement/seed tempo.
  setTempoOverride(bpm) {
    if (bpm === null || bpm === undefined || !Number.isFinite(bpm)) {
      this.tempoOv = null;
      return;
    }
    this.tempoOv = Math.max(BPM_MIN, Math.min(BPM_MAX, Math.round(bpm)));
    this.curBpm = this.tempoOv;
  }

  // Tonality chosen by hand. key: -1 (from the place) or 0..11. scale: 'auto'
  // (the place decides, sometimes inventing a scale or using quarter tones),
  // 'procedural' (a scale invented for this place) or any name in SCALES.
  // quarter: allow quarter tones in the automatic and procedural choices.
  // Applies at the next bar line by re-latching the current place.
  setTone(key, scale, quarter) {
    const k = Number.isInteger(key) && key >= 0 && key < 12 ? key : -1;
    const sc = scale === 'procedural' || (typeof scale === 'string' && Object.prototype.hasOwnProperty.call(SCALES, scale)) ? scale : 'auto';
    const q = quarter !== false;
    const t = this.tone;
    if (t.key === k && t.scale === sc && t.quarter === q) return;
    this.tone = { key: k, scale: sc, quarter: q };
    if (this.lastIn && !this.pending) this.pending = this.lastIn;
  }

  // Force the lead line on (the user picked a lead instrument) and keep it in
  // that instrument's range. ov = { lo, hi } midi notes, or null for the
  // style's own arrangement.
  setLeadOverride(ov) {
    this.leadOv = ov ? { lo: ov.lo, hi: ov.hi } : null;
  }

  // Procedural lead: every place invents its own instrument (see instrument.js)
  // and the melody stays in that instrument's register. Replaces a lead override.
  setLeadProcedural(on) {
    this.leadProc = !!on;
  }

  info() {
    const s = this.s;
    if (!s) return null;
    return {
      leadName: this.leadProc && s.instV ? s.instV.name : null,
      style: s.styleIdx,
      styleName: s.style.name,
      key: NOTE_NAMES[s.pc],
      scale: s.scaleName,
      scaleSteps: s.scaleSteps,
      micro: s.scale.some((x) => x !== Math.floor(x)),
      bpm: this.curBpm === null ? s.bpm : this.curBpm,
    };
  }

  // ---------------------------------------------------------------- latching

  _latch(seed) {
    const prev = this.s;
    const styleIdx =
      seed.style >= 0 && seed.style < STYLES.length
        ? seed.style
        : mix32(seed.coarse ^ 0x57) % STYLES.length;
    const style = STYLES[styleIdx];
    const full = !prev || prev.styleIdx !== styleIdx || prev.coarse !== seed.coarse;
    if (full) this.curBpm = null; // new place/style: take its tempo straight away

    const s = {
      styleIdx,
      style,
      coarse: seed.coarse,
      fine: seed.fine,
      sectionIdx: 0,
      barInSection: 0,
      sectionBars: 0,
      prog: [0, 0, 0, 0],
      motifSeed: 1,
      layers: {},
      bright: 0.5,
      densMul: 1,
      groove: null,
      seqPat: [],
      seqGate: [],
      answer: false,
      leadMidi: 74,
      hum: stream(seed.fine, 77),
    };

    // Key, mode and tempo come from the coarse cell (stable over ~10 km).
    const kr = stream(seed.coarse, 11);
    s.pc = kr.below(12);
    s.scaleName = style.scales[kr.below(style.scales.length)];
    // Tonality: the style's own modes, unless the place (or the user) picks a
    // quarter-tone or an invented scale. Own PRNG streams, so the draws above
    // stay as they were.
    const tone = this.tone;
    if (tone.key >= 0) s.pc = tone.key;
    const tr = stream(seed.coarse, 903);
    const roll = tr.float();
    const microPick = MICRO_NAMES[tr.below(MICRO_NAMES.length)];
    let want = tone.scale;
    if (want === 'auto') {
      want = s.scaleName;
      if (roll < 0.22) want = 'procedural';
      else if (tone.quarter && roll < 0.38) want = microPick;
    }
    s.scaleSteps = null;
    s.scaleInfo = SCALE_INFO[want];
    if (want === 'procedural') {
      const ps = makeProceduralScale(stream(seed.coarse, 904), tone.quarter);
      s.scaleName = 'procedural';
      s.scale = ps.scale;
      s.scaleSteps = ps.steps;
      s.scaleInfo = ps.info;
    } else {
      s.scaleName = want;
      s.scale = SCALES[want];
    }
    if (style.pent && PENT_OK.includes(s.scaleName)) {
      const major = ['ionian', 'lydian', 'mixolydian'].includes(s.scaleName);
      s.melScale = major ? PENT.major : PENT.minor;
    } else {
      s.melScale = s.scale;
    }
    s.bpm = style.bpm[0] + kr.below(style.bpm[1] - style.bpm[0] + 1);

    // The place's own lead instrument (changes with the coarse cell, like style and key).
    s.inst = makeInstrument(stream(seed.coarse, 901));
    s.instV = s.inst;

    s.sectionBars = 8 * style.chordBars;
    this.s = s;
    this._newSection(full);
  }

  _newSection(intro) {
    const s = this.s;
    const style = s.style;
    const secSeed = mix32((s.fine ^ Math.imul(s.sectionIdx + 1, 0x9e3779b1)) >>> 0);
    const r = stream(secSeed, 1);

    // Harmony: keep the last progression 40% of the time so ideas come back.
    const keepProg = s.sectionIdx > 0 && r.chance(0.4);
    const pr = stream(secSeed, 2);
    if (!keepProg) {
      s.prog = makeProgression(pr, s.scaleInfo, 4, style.stay, style.starts);
    }
    if (!(s.sectionIdx > 0 && r.chance(0.5))) s.motifSeed = stream(secSeed, 3).next();
    s.answer = r.chance(0.6);
    s.instV = morphInstrument(s.inst, stream(secSeed, 902));

    // Arrangement: which layers play in this section.
    const layers = {};
    if (intro) {
      const cand = ['pad', 'bass', 'arp']
        .map((n) => [n, style.layerProb[n]])
        .sort((a, b) => b[1] - a[1])
        .slice(0, 2);
      for (const n of LAYERS) layers[n] = false;
      for (const [n] of cand) layers[n] = true;
      if (style.introDrums) layers.drums = true; // e.g. techno opens with the kick
    } else {
      let count = 0;
      for (const n of LAYERS) {
        layers[n] = r.chance(style.layerProb[n]);
        if (layers[n]) count++;
      }
      if (count < 2) {
        const top = LAYERS.map((n) => [n, style.layerProb[n]])
          .sort((a, b) => b[1] - a[1])
          .slice(0, 2);
        for (const [n] of top) layers[n] = true;
      }
    }
    if (!style.drums) layers.drums = false;
    s.layers = layers;

    s.bright = style.bright[0] + r.float() * (style.bright[1] - style.bright[0]);
    s.densMul = 0.6 + r.float() * 0.8;

    // Drum groove for the whole section.
    if (style.drums) {
      const d = style.drums;
      const kick = style.drums.kick ? pat(d.kick) : [];
      const gr = stream(secSeed, 4);
      for (const g of [3, 7, 10, 11, 14, 15]) {
        if (gr.chance(d.ghost * 0.4) && !kick.includes(g)) kick.push(g);
      }
      s.groove = { kick, snare: d.snare ? pat(d.snare) : [] };
    }

    // Arpeggio "seq" mode pattern.
    const sr = stream(secSeed, 5);
    s.seqPat = [];
    s.seqGate = [];
    for (let i = 0; i < 16; i++) {
      s.seqPat.push(sr.below(6));
      s.seqGate.push(sr.chance(0.78) ? 1 : 0);
    }

    s.barInSection = 0;
    s.secSeed = secSeed;
  }

  // ---------------------------------------------------------------- planning

  nextBar() {
    if (this.pending) {
      this.lastIn = this.pending;
      this._latch(this.pending);
      this.pending = null;
      this.barCount = 0;
    } else if (!this.s) {
      this._latch({ style: -1, coarse: 1, fine: 1 });
    }
    let s = this.s;
    if (s.barInSection >= s.sectionBars) {
      s.sectionIdx++;
      this._newSection(false);
    }

    const style = s.style;

    // Tempo: from the seed, or following movement speed. Moves at most
    // MAX_BPM_STEP per bar so changes feel like accelerating, not jumping.
    let targetBpm = s.bpm;
    if (this.tempoFactor !== null) {
      const lo = style.bpm[0] * 0.9;
      const hi = Math.max(style.bpm[1] * 1.1, FOLLOW_TOP_BPM);
      targetBpm = Math.round(lo + this.tempoFactor * (hi - lo));
    }
    if (this.tempoOv !== null) this.curBpm = this.tempoOv;
    else if (this.curBpm === null) this.curBpm = targetBpm;
    else this.curBpm += Math.max(-MAX_BPM_STEP, Math.min(MAX_BPM_STEP, targetBpm - this.curBpm));

    const cb = style.chordBars;
    const j = s.barInSection;
    const prog = s.prog;
    const progLen = 4 * cb;
    const jj = j % progLen;
    const chordIdx = Math.floor(jj / cb);
    const posInChord = jj % cb;
    const repeat = Math.floor(j / progLen);
    const nextChordIdx = (chordIdx + (posInChord === cb - 1 ? 1 : 0)) % 4;
    const degree = prog[chordIdx];
    const nextDegree = prog[nextChordIdx];
    const lastBar = j === s.sectionBars - 1;

    const rr = stream(s.secSeed, 200 + j);
    const opts = {
      seventh: stream(s.secSeed, 300 + chordIdx).chance(style.sevenths),
      sus: null,
    };
    const susR = stream(s.secSeed, 400 + chordIdx);
    if (susR.chance(style.sus)) opts.sus = susR.chance(0.5) ? '2' : '4';
    const tones = chordTones(s.scale, degree, opts);

    const steps = [];
    for (let i = 0; i < STEPS_PER_BAR; i++) steps.push([]);
    const L = s.layers;
    const hum = s.hum;

    // ---- pad
    if (L.pad && posInChord === 0) {
      const notes = tones.map((t) => fold(48 + s.pc + t, 55)).sort((a, b) => a - b);
      if (!L.bass) notes.unshift(fold(48 + s.pc + tones[0], 43));
      for (const n of notes) {
        steps[0].push({ voice: 'pad', note: n, vel: 0.5 + hum.float() * 0.08, len: STEPS_PER_BAR * cb });
      }
    }

    // ---- bass
    if (L.bass) this._planBass(steps, s, tones, degree, nextDegree, posInChord, rr, hum);

    // ---- arp
    if (L.arp) this._planArp(steps, s, tones, j, hum);

    // ---- lead
    if (L.lead || this.leadOv || this.leadProc) this._planLead(steps, s, tones, j, jj, repeat, progLen, cb, lastBar);

    // ---- drums
    if (L.drums && style.drums) this._planDrums(steps, s, j, lastBar, rr, hum);

    const t = s.sectionBars > 1 ? j / (s.sectionBars - 1) : 0;
    const plan = {
      steps,
      bpm: this.curBpm,
      swing: style.swing,
      swing8: style.swing8 || 0,
      fx: style.fx,
      patches: style.patches,
      bright: s.bright * (0.78 + 0.22 * t),
      bar: this.barCount,
      section: s.sectionIdx,
      chordDegree: degree,
      trim: style.trim || 1,
      duck: L.drums && style.drums ? 0.4 : 0,
      layers: { ...L, lead: !!(L.lead || this.leadOv || this.leadProc) },
      leadSynth: this.leadProc && !this.leadOv ? s.instV : null,
    };
    s.barInSection++;
    this.barCount++;
    return plan;
  }

  _planBass(steps, s, tones, degree, nextDegree, posInChord, rr, hum) {
    const style = s.style;
    const cb = style.chordBars;
    const root = fold(36 + s.pc + s.scale[degree], 36);
    const mode = style.bass.mode;
    const push = (st, note, vel, len) =>
      steps[st].push({ voice: 'bass', note, vel: vel * (0.92 + hum.float() * 0.08), len });
    if (mode === 'sub' || mode === 'drone') {
      if (posInChord === 0) push(0, root, 0.8, STEPS_PER_BAR * cb - 0.5);
    } else if (mode === 'pulse') {
      const fifth = rr.chance(0.3);
      for (let st = 0; st < 16; st += 2) {
        const n = st === 14 && fifth ? root + 7 : root;
        push(st, n, st % 8 === 0 ? 0.85 : 0.65, 1.7);
      }
    } else if (mode === 'offbeat') {
      for (let st = 2; st < 16; st += 4) push(st, root, 0.8, 1.6);
    } else if (mode === 'octave') {
      for (let st = 0; st < 16; st += 2) push(st, st % 4 === 2 ? root + 12 : root, 0.7, 1.2);
    } else if (mode === 'acid') {
      // 16th-note acid line. The kick owns the beat, so the bass plays the gaps;
      // the section's random pattern picks which gaps, which note and which
      // steps are accented (and open the filter wider).
      const third = fold(36 + s.pc + tones[1], 36);
      const fifth = fold(36 + s.pc + tones[2], 36);
      const pick = [root, root, root + 12, third, fifth, root + 12];
      for (let st = 0; st < 16; st++) {
        if (st % 4 === 0 || !s.seqGate[st]) continue;
        const k = s.seqPat[(st * 5 + 3) & 15];
        push(st, pick[k], k >= 4 ? 0.95 : 0.66, 1.3);
      }
    } else if (mode === 'walk') {
      const nextRoot = fold(36 + s.pc + s.scale[nextDegree], 36);
      const third = root + (s.scale[(degree + 2) % 7] - s.scale[degree] + 12) % 12;
      const fifth = root + 7;
      const approach = nextRoot + (rr.chance(0.5) ? -1 : 1);
      const seq = [root, rr.chance(0.5) ? third : fifth, fifth, approach];
      for (let i = 0; i < 4; i++) push(i * 4, seq[i], i === 0 ? 0.85 : 0.65, 3.6);
    }
  }

  _planArp(steps, s, tones, j, hum) {
    const a = s.style.arp;
    const rate = a.rate;
    const pool = [];
    const base = tones.map((t) => fold(48 + s.pc + t, 60)).sort((x, y) => x - y);
    for (let o = 0; o < a.octaves; o++) for (const n of base) pool.push(n + 12 * o);
    const N = pool.length;
    const ar = stream(s.secSeed, 500 + j);
    for (let st = 0, k = 0; st < 16; st += rate, k++) {
      // Draw unconditionally so patterns stay in sync when options change.
      const pick = ar.below(N);
      const skip = ar.float();
      let idx;
      let play = true;
      switch (a.mode) {
        case 'up':
          idx = k % N;
          break;
        case 'down':
          idx = N - 1 - (k % N);
          break;
        case 'updown': {
          const period = Math.max(1, 2 * N - 2);
          const m = k % period;
          idx = m < N ? m : period - m;
          break;
        }
        case 'seq':
          idx = s.seqPat[st] % N;
          play = s.seqGate[st] === 1;
          break;
        default:
          idx = pick;
          play = skip > 0.3;
      }
      if (!play) continue;
      const accent = st % 4 === 0 ? 1.12 : 0.92;
      steps[st].push({
        voice: 'arp',
        note: pool[idx],
        vel: a.vel * accent * (0.9 + hum.float() * 0.1),
        len: rate * a.gate,
      });
    }
  }

  _planLead(steps, s, tones, j, jj, repeat, progLen, cb, lastBar) {
    const style = s.style;
    const key = repeat === 1 && jj === progLen - 1 && s.answer ? 99 : jj % (2 * cb);
    const r = stream(s.motifSeed, 31 * key + 7);
    let dens = Math.min(0.9, style.lead.density * s.densMul);
    const forced = this.leadOv || this.leadProc;
    if (forced) dens = Math.max(dens, 0.26);
    const mel = s.melScale;
    const origin = 48 + s.pc;
    let lo = style.lead.lo || 62;
    let hi = style.lead.hi || 88;
    if (this.leadOv) {
      lo = this.leadOv.lo;
      hi = this.leadOv.hi;
    } else if (this.leadProc) {
      lo = s.instV.lo;
      hi = s.instV.hi;
    }

    // Chord tones across the lead register, as midi notes.
    const ctMidi = [];
    for (let o = -2; o <= 4; o++) for (const t of tones) ctMidi.push(origin + t + 12 * o);
    const nearestChordTone = (m) => {
      let best = ctMidi[0];
      let bd = 1e9;
      for (const c of ctMidi) {
        const d = Math.abs(c - m);
        if (d < bd) {
          bd = d;
          best = c;
        }
      }
      return best;
    };

    const hits = [];
    let last = -99;
    let idx = nearestIdx(mel, s.leadMidi - origin);
    const deltas = [-3, -2, -2, -1, -1, -1, 0, 1, 1, 1, 2, 2, 3];
    for (let st = 0; st < 16; st++) {
      const chance = r.float();
      const delta = deltas[r.below(deltas.length)];
      const snap = r.float();
      const velJ = r.float();
      const p = Math.min(1, dens * 3.2 * METER[st]);
      if (chance < p && st - last >= style.lead.minGap) {
        let m = origin + scaleNote(mel, idx + delta);
        idx += delta;
        if (hits.length === 0 || (st % 4 === 0 && snap < 0.65)) {
          m = nearestChordTone(m);
          idx = nearestIdx(mel, m - origin);
        }
        while (m > hi) {
          idx -= mel.length;
          m -= 12;
        }
        while (m < lo) {
          idx += mel.length;
          m += 12;
        }
        hits.push({ st, m, vel: style.lead.vel * (METER[st] > 0.5 ? 1 : 0.85) * (0.88 + velJ * 0.12) });
        last = st;
      }
    }
    for (let i = 0; i < hits.length; i++) {
      const h = hits[i];
      const next = i + 1 < hits.length ? hits[i + 1].st : 16;
      const len = Math.max(1, Math.min(next - h.st, 8) * 0.92);
      steps[h.st].push({ voice: 'lead', note: h.m, vel: h.vel, len });
      s.leadMidi = h.m;
    }
  }

  _planDrums(steps, s, j, lastBar, rr, hum) {
    const d = s.style.drums;
    const lvl = d.level;
    const g = s.groove;
    const add = (st, voice, note, vel, len) =>
      steps[st].push({ voice, note, vel: Math.min(1, vel * lvl * (0.93 + hum.float() * 0.07)), len: len || 1 });

    for (const st of g.kick) add(st, 'kick', 36, [0, 8].includes(st) || st % 4 === 0 ? 1.0 : 0.6);
    for (const st of g.snare) {
      if (lastBar && st === 12) continue;
      add(st, 'snare', 38, 0.85);
    }
    const hat = d.hat;
    if (hat === 'eighth') {
      for (let st = 0; st < 16; st += 2) add(st, 'hat', 42, st % 4 === 2 ? 0.55 : 0.35);
    } else if (hat === 'offbeat') {
      for (let st = 2; st < 16; st += 4) add(st, 'hat', 46, 0.5, 2);
    } else if (hat === 'sixteenth') {
      // Closed 16ths with an open hat on every off-beat eighth.
      for (let st = 0; st < 16; st++) {
        if (st % 4 === 2) add(st, 'hat', 46, 0.5, 2);
        else add(st, 'hat', 42, st % 2 ? 0.22 : 0.34);
      }
    } else if (hat === 'sparse') {
      for (let st = 0; st < 16; st += 2) if (rr.chance(0.35)) add(st, 'hat', 42, 0.3);
    }
    if (lastBar) {
      // Fill: snare roll, or toms when the style has no snare.
      if (d.snare && s.style.id !== 'epic') {
        for (let k = 0; k < 4; k++) add(12 + k, 'snare', 38, 0.5 + k * 0.14);
      } else {
        const toms = [50, 47, 45, 43];
        for (let k = 0; k < 4; k++) add(12 + k, 'tom', toms[k], 0.7 + k * 0.08, 2);
      }
    }
  }
}


